public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    try {
        int length = schema.getSerializedSize(message);
        byte[] lengthBytes = ByteBuffer.allocate(4).putInt(length).array();
        out.write(lengthBytes);
        schema.writeBytes(message, buffer);
        out.write(buffer.buffer.array(), buffer.offset, buffer.size);
        buffer.clear();
        return length + buffer.size;
    } catch (IOException e) {
        throw e;
    }
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int headerSize = CodedOutputStream.computeInt32SizeNoTag(message, schema, buffer);
    ByteBuffer header = ByteBuffer.allocate(headerSize);
    CodedOutputStream headerCodedOut = CodedOutputStream.newInstance(header);
    headerCodedOut.writeVarint32NoTag(message, schema, buffer);
    headerCodedOut.flush();
    out.write(header.array());
    buffer.clear();
    int messageSize = schema.writeTo(buffer, message);
    out.write(buffer.buf, buffer.offset, messageSize);
    buffer.clear();
    return headerSize + messageSize;
}

