protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long fetchDataDuration = 3600000L; // 1 hour in milliseconds
    long interval = end - start;

    if (interval <= fetchDataDuration) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        while (start < end) {
            long nextEnd = Math.min(start + fetchDataDuration, end);
            timeRanges.add(new TimeRange(start, nextEnd));
            start = nextEnd;
        }
    }

    return timeRanges;
}

