static long compressTimeBucket(long timeBucket, int dayStep) {
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    if (dayStep == 1) {
        return timeBucket;
    }

    int daysToSubtract = (day - 1) % dayStep + 1;
    day -= daysToSubtract;

    if (day == 0) {
        month--;
        if (month == 0) {
            year--;
            month = 12;
        }
        day = 31;
    } else {
        for (int i = month - 1; i >= 0; i--) {
            if (i == 1) {
                if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
                    if (day > 29) day = 29;
                } else {
                    if (day > 28) day = 28;
                }
            } else if (i % 2 == 0 && i != 8) {
                if (day > 30) day = 30;
            } else {
                if (day > 31) day = 31;
            }
            if (day != 0) break;
            day += 31;
            month--;
        }
    }

    return year * 10000L + month * 100 + day;
}

