private static LinkedBuffer expandBuffer(LinkedBuffer lb, int additionalLength) {
    int newSize = Math.max(lb.buffer.length * 2, lb.buffer.length + additionalLength);
    byte[] newBuffer = new byte[newSize];
    System.arraycopy(lb.buffer, 0, newBuffer, 0, lb.offset);
    return new LinkedBuffer(newBuffer, lb.offset);
}

