        if (types[i] == UTF8 && utf8s[i].equals(s)) {
            return i;
        }
    }
    types[maxPoolSize] = UTF8;
    utf8s[maxPoolSize] = s;
    return maxPoolSize++;
}

public int findUtf8(final String s) {
    for (int i = START_OF_CONSTANT_POOL; i < maxPoolSize; i++) {
        if (types[i] == UTF8 && utf8s[i].equals(s)) {
            return i;
        }
    }
    return -1;
}

public int findNameAndType(final int nameIndex, final int descriptorIndex) {
    for (int i = START_OF_CONSTANT_POOL; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE && findUtf8(types[i + 2] == UTF8 ? utf8s[i + 1] : null) == nameIndex &&
            findUtf8(types[i + 3] == UTF8 ? utf8s[i + 2] : null) == descriptorIndex) {
            return i;
        }
    }
    return -1;
}

public int newConstantNameAndType(final int nameIndex, final int descriptorIndex) {
    types[maxPoolSize] = NAME_TYPE;
    types[maxPoolSize + 1] = 0; // length (will be filled later)
    types[maxPoolSize + 2] = nameIndex;
    types[maxPoolSize + 3] = descriptorIndex;
    int length = 5 + 4 * (nameIndex < 256 ? 1 : 2) + 4 * (descriptorIndex < 256 ? 1 : 2);
    types[maxPoolSize + 1] = (byte) (length >> 8);
    types[maxPoolSize + 1] |= (byte) length;
    maxPoolSize += 4;
    return maxPoolSize - 4;
}

